// Configuração da análise e do resumo do Espião de Anúncios.
// Edite só os valores abaixo. As chaves ficam nas credenciais do n8n, nunca aqui.
const config = {
  // Projeto do Supabase onde você rodou o 001_schema.sql
  supabase_url: "https://SEU-PROJETO.supabase.co",

  // Modelo da OpenAI que classifica cada anúncio (mais barato)
  openai_model_analysis: "gpt-5-mini",

  // Modelo da OpenAI que escreve o resumo da semana
  openai_model_digest: "gpt-5",

  // Máximo de anúncios novos analisados por execução (controle de custo)
  analysis_limit: 150,

  // Período coberto pelo resumo, em dias
  report_days: 7,

  // Instância da uazapi que envia o resumo no WhatsApp
  uazapi_url: "https://SUA-INSTANCIA.uazapi.com",

  // Números que recebem o resumo, com DDI e DDD. Exemplo ['5511999999999']
  digest_numbers: [],

  // Quem somos. A IA usa isso para adaptar as ideias. Quanto mais específico, melhor.
  company_context: `
Empresa: [NOME DA EMPRESA]
O que vendemos: [ex.: serviços gerenciados de TI, outsourcing de TI, suporte e infraestrutura]
Para quem: [ex.: empresas de 20 a 300 funcionários, setores, região]
Diferenciais: [PREENCHER]
Ticket e modelo de contrato: [PREENCHER]
Canais de aquisição hoje: [ex.: Instagram, LinkedIn, indicação]
`.trim(),
};

return [{ json: config }];

// Builds one OpenAI request per ad that still has no analysis.

const WRITING_RULES = [
  'Escreva em português do Brasil, direto e concreto.',
  'Não use travessão nem meia-risca. Use vírgula, ponto ou parênteses.',
  'Não use dois-pontos para criar efeito ou suspense.',
  'Não use a construção "não é X, é Y" nem "não X, mas Y".',
  'Não use frases de antecipação do tipo "e é aqui que tudo muda".',
  'Não empilhe frases curtas em sequência rítmica.',
  'Não use ênclise nem mesóclise. Prefira próclise ou reescreva a frase.',
].join('\n');

const PAINS = [
  'cyber_security', 'lgpd_compliance', 'it_cost', 'downtime_productivity', 'lack_of_it_team',
  'cloud_migration', 'microsoft_365', 'backup_recovery', 'helpdesk_support', 'network_infrastructure',
  'growth_scale', 'ai_automation', 'digital_transformation', 'none', 'other',
];
const OFFERS = [
  'free_assessment', 'lead_magnet', 'webinar_event', 'demo', 'quote_contact', 'free_trial',
  'price_promo', 'brand_awareness', 'recruiting', 'other',
];
const PROOFS = [
  'numbers_results', 'client_cases', 'testimonial', 'certifications_partners', 'years_in_market',
  'awards', 'client_logos', 'none',
];

const ANALYSIS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: [
    'is_relevant', 'summary', 'creative_format', 'visual_style', 'image_text', 'pain', 'angle', 'offer',
    'funnel_stage', 'hook', 'cta', 'destination', 'proof', 'target_audience', 'tone',
    'inspiration_score', 'idea_for_us',
  ],
  properties: {
    is_relevant: {
      type: 'boolean',
      description: 'true quando o anúncio vende serviços de TI ou tecnologia para empresas (B2B). false para vaga de emprego, venda ao consumidor final ou assunto fora do nicho.',
    },
    summary: { type: 'string', description: 'Uma frase dizendo o que o anúncio vende e para quem.' },
    creative_format: {
      type: 'string',
      enum: ['static_image', 'carousel', 'video', 'text_only', 'document', 'message', 'other'],
    },
    visual_style: {
      type: 'string',
      description: 'Descrição curta do visual (ex.: foto de pessoa com texto grande, print de dashboard, ilustração 3D). Use "sem imagem" quando não houver.',
    },
    image_text: { type: ['string', 'null'], description: 'Texto escrito dentro da imagem, quando houver.' },
    pain: { type: 'string', enum: PAINS, description: 'Dor principal que o anúncio ataca.' },
    angle: { type: 'string', description: 'Como o anúncio ataca a dor, em uma frase.' },
    offer: { type: 'string', enum: OFFERS, description: 'O que o anúncio oferece em troca do clique.' },
    funnel_stage: { type: 'string', enum: ['top', 'middle', 'bottom'] },
    hook: { type: 'string', description: 'A primeira frase ou ideia que prende a atenção.' },
    cta: { type: ['string', 'null'], description: 'Chamada para ação, como aparece no anúncio.' },
    destination: {
      type: 'string',
      enum: ['landing_page', 'native_form', 'whatsapp', 'website', 'event_page', 'unknown'],
    },
    proof: { type: 'array', items: { type: 'string', enum: PROOFS } },
    target_audience: { type: 'string', description: 'Quem parece ser o alvo (porte, cargo, setor).' },
    tone: {
      type: 'string',
      enum: ['technical', 'consultative', 'fear_based', 'aspirational', 'humorous', 'institutional'],
    },
    inspiration_score: {
      type: 'integer',
      enum: [1, 2, 3, 4, 5],
      description: '1 a 5. Quanto esse anúncio serve de referência para nós (clareza da oferta, força do gancho, tempo no ar).',
    },
    idea_for_us: {
      type: 'string',
      description: 'Uma ideia prática de anúncio inspirada neste, adaptada à nossa empresa, sem copiar o texto.',
    },
  },
};

function supportsReasoningEffort(model) {
  return /^(gpt-5|o\d)/.test(model);
}

function describeAd(ad) {
  const lines = [
    `Plataforma: ${ad.platform}`,
    `Anunciante: ${ad.competitor_name || ad.advertiser_name || 'desconhecido'}`,
    `Formato informado pela plataforma: ${ad.format || 'desconhecido'}`,
    `Dias no ar até agora: ${ad.days_running ?? 'desconhecido'}`,
    `Variações do anúncio: ${ad.variations ?? 'desconhecido'}`,
    `Título: ${ad.headline || '(sem título)'}`,
    `Texto: ${ad.body || '(sem texto)'}`,
    `CTA: ${ad.cta || '(sem CTA)'}`,
    `Link de destino: ${ad.link_url || '(desconhecido)'}`,
  ];
  if (ad.video_url) lines.push('O anúncio é um vídeo. A imagem anexada, quando existe, é a capa do vídeo.');
  return lines.join('\n');
}

function buildAnalysisRequest(ad, config) {
  const useImage = Boolean(ad.image_url) && (ad.analysis_attempts || 0) === 0;
  const content = [{ type: 'text', text: describeAd(ad) }];
  if (useImage) content.push({ type: 'image_url', image_url: { url: ad.image_url, detail: 'low' } });

  const body = {
    model: config.openai_model_analysis,
    messages: [
      {
        role: 'system',
        content: [
          'Você é analista de mídia paga especializado em empresas de serviços de TI no Brasil (MSPs, outsourcing de TI, cloud, segurança).',
          'Analise o anúncio de um concorrente e classifique cada campo do schema.',
          'Use só o que está no anúncio. Quando faltar informação, escolha "unknown", "other" ou null.',
          'Anúncio com muitos dias no ar provavelmente está dando resultado. Leve isso em conta na nota de inspiração.',
          '',
          'Contexto da nossa empresa, para o campo idea_for_us:',
          config.company_context,
          '',
          'Regras de escrita para os campos de texto:',
          WRITING_RULES,
        ].join('\n'),
      },
      { role: 'user', content },
    ],
    response_format: {
      type: 'json_schema',
      json_schema: { name: 'ad_analysis', strict: true, schema: ANALYSIS_SCHEMA },
    },
  };
  if (supportsReasoningEffort(config.openai_model_analysis)) body.reasoning_effort = 'low';

  return {
    ad_id: ad.id,
    attempts: ad.analysis_attempts || 0,
    used_image: useImage,
    model: config.openai_model_analysis,
    openai_body: body,
  };
}

function parseJsonList(text) {
  if (Array.isArray(text)) return text;
  if (typeof text !== 'string' || text.trim() === '') return [];
  const parsed = JSON.parse(text);
  if (!Array.isArray(parsed)) throw new Error(`Expected a JSON array from Supabase, got: ${text.slice(0, 200)}`);
  return parsed;
}

// @n8n-entry
const config = $('Config').first().json;
const ads = parseJsonList($('Buscar anúncios pendentes').first().json.body);
return ads.map((ad) => ({ json: buildAnalysisRequest(ad, config) }));

// Reads the OpenAI answer for one ad and builds the PATCH for spy_ads.

function readOpenAiResponse(response) {
  const status = Number(response.statusCode) || 0;
  let body = response.body ?? response.data ?? null;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch {
      return { ok: false, error: `Invalid JSON from OpenAI (HTTP ${status})` };
    }
  }
  if (status < 200 || status >= 300) {
    const message = body && body.error ? body.error.message || body.error.type : `HTTP ${status}`;
    return { ok: false, error: `OpenAI HTTP ${status}: ${String(message).slice(0, 400)}` };
  }
  const message = body && body.choices && body.choices[0] && body.choices[0].message;
  if (!message) return { ok: false, error: 'OpenAI returned no message' };
  if (message.refusal) return { ok: false, error: `OpenAI refused: ${String(message.refusal).slice(0, 300)}` };
  try {
    return { ok: true, analysis: JSON.parse(message.content), usage: body.usage || null };
  } catch {
    return { ok: false, error: 'OpenAI content is not valid JSON' };
  }
}

function buildAnalysisPatch(request, response, now) {
  const result = readOpenAiResponse(response);
  if (!result.ok) {
    return {
      ad_id: request.ad_id,
      patch: { analysis_attempts: request.attempts + 1, analysis_error: result.error },
    };
  }
  return {
    ad_id: request.ad_id,
    patch: {
      analysis: {
        ...result.analysis,
        model: request.model,
        used_image: request.used_image,
        tokens: result.usage ? result.usage.total_tokens : null,
      },
      analyzed_at: now.toISOString(),
      analysis_attempts: request.attempts + 1,
      analysis_error: null,
    },
  };
}

// @n8n-entry
const request = $('Preparar análises').item.json;
return { json: buildAnalysisPatch(request, $json, new Date()) };

// Builds the OpenAI request that writes the weekly WhatsApp digest.

const WRITING_RULES = [
  'Não use travessão nem meia-risca. Use vírgula, ponto ou parênteses.',
  'Não use dois-pontos. Para rótulos, quebre a linha.',
  'Não use a construção "não é X, é Y" nem "não X, mas Y".',
  'Não use frases de antecipação do tipo "e é aqui que tudo muda".',
  'Não empilhe frases curtas em sequência rítmica.',
  'Não use ênclise nem mesóclise. Prefira próclise ou reescreva a frase.',
].join('\n');

const LABELS = [
  'Rótulos usados nos dados (traduza ao escrever):',
  'pain: cyber_security=segurança/ataques, lgpd_compliance=LGPD, it_cost=custo de TI, downtime_productivity=parada e produtividade, lack_of_it_team=falta de equipe de TI, cloud_migration=migração para nuvem, microsoft_365=Microsoft 365, backup_recovery=backup, helpdesk_support=suporte/helpdesk, network_infrastructure=rede e infraestrutura, growth_scale=crescimento, ai_automation=IA e automação, digital_transformation=transformação digital',
  'offer: free_assessment=diagnóstico gratuito, lead_magnet=material rico, webinar_event=webinar/evento, demo=demonstração, quote_contact=orçamento/contato, free_trial=teste grátis, price_promo=preço/promoção, brand_awareness=marca, recruiting=vagas',
  'funnel_stage: top=topo, middle=meio, bottom=fundo',
].join('\n');

function formatDate(iso) {
  const date = new Date(iso);
  const day = String(date.getUTCDate()).padStart(2, '0');
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  return `${day}/${month}`;
}

function supportsReasoningEffort(model) {
  return /^(gpt-5|o\d)/.test(model);
}

function buildDigestRequest(report, config) {
  const period = report.period || {};
  const title = `Espião de anúncios · ${formatDate(period.from)} a ${formatDate(period.to)}`;
  const instructions = [
    'Você escreve o resumo semanal de inteligência de anúncios de concorrentes para o dono de uma empresa de serviços de TI.',
    'O resumo vai pelo WhatsApp. Use *negrito* do WhatsApp, listas com "•" e linhas em branco entre seções. Nada de títulos markdown, tabelas ou links encurtados.',
    'Máximo de 3.500 caracteres.',
    '',
    'Estrutura, nesta ordem, pulando a seção que não tiver dados:',
    `1. Primeira linha *${title}*. Na linha seguinte, os números da semana (anúncios ativos, novos, pausados e a divisão por plataforma).`,
    '2. *Movimentos dos concorrentes*. Até 6 concorrentes com o que mudou na semana.',
    '3. *Anúncios que estão durando*. Até 4 anúncios ativos há mais tempo, que provavelmente dão resultado. Para cada um, a dor, a oferta, o gancho e o link da biblioteca.',
    '4. *Padrões*. As dores, ofertas e formatos que mais aparecem nos anúncios ativos.',
    '5. *Ideias para nós*. De 3 a 5 ideias concretas de anúncio (formato, gancho, oferta e CTA) adaptadas ao contexto da nossa empresa. Inspire-se nos padrões e nos anúncios que duram, sem copiar texto de concorrente.',
    '6. *Anunciantes novos no radar*. Até 5 anunciantes achados pelas palavras-chave que ainda não monitoramos.',
    '7. Se collection_health tiver falhas, uma linha final avisando quais coletas falharam.',
    '',
    'Se houver poucos dados (por exemplo, na primeira semana), diga isso em uma frase e trabalhe com o que existe. Nunca invente número, anúncio ou concorrente que não esteja nos dados.',
    '',
    'Regras de escrita:',
    WRITING_RULES,
    '',
    LABELS,
  ].join('\n');

  const body = {
    model: config.openai_model_digest,
    messages: [
      { role: 'system', content: instructions },
      {
        role: 'user',
        content: [
          'Contexto da nossa empresa:',
          config.company_context,
          '',
          'Dados da semana (JSON):',
          JSON.stringify(report),
        ].join('\n'),
      },
    ],
  };
  if (supportsReasoningEffort(config.openai_model_digest)) body.reasoning_effort = 'medium';
  return { title, report, openai_body: body };
}

// @n8n-entry
const config = $('Config').first().json;
let report = $input.first().json;
if (typeof report.body === 'string') report = JSON.parse(report.body);
return [{ json: buildDigestRequest(report, config) }];

// Extracts the digest text from OpenAI. Falls back to a plain summary if the model fails,
// so the weekly message always goes out.

const MAX_CHARS = 4000;

function fallbackMessage(title, report, error) {
  const totals = report.totals || {};
  const byPlatform = Object.entries(totals.active_by_platform || {})
    .map(([platform, count]) => `${platform} ${count}`)
    .join(', ');
  const lines = [
    `*${title}*`,
    `Anúncios ativos ${totals.active_ads ?? 0} (${byPlatform || 'sem dados'}). Novos ${totals.new_ads ?? 0}. Pausados ${totals.stopped_ads ?? 0}.`,
    '',
    `A IA não conseguiu escrever o resumo desta semana (${error}). Os dados estão salvos no Supabase, na tabela spy_digests.`,
  ];
  return lines.join('\n');
}

function extractDigest(request, response) {
  const status = Number(response.statusCode) || 0;
  let body = response.body ?? response.data ?? null;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch {
      body = null;
    }
  }
  const content = body && body.choices && body.choices[0] && body.choices[0].message && body.choices[0].message.content;
  if (status >= 200 && status < 300 && typeof content === 'string' && content.trim() !== '') {
    const text = content.trim().replace(/\s*[—–]\s*/g, ', ');
    return { message: text.length > MAX_CHARS ? `${text.slice(0, MAX_CHARS - 1)}…` : text, ai_ok: true };
  }
  const error = body && body.error ? body.error.message || body.error.type : `HTTP ${status}`;
  return { message: fallbackMessage(request.title, request.report, String(error).slice(0, 200)), ai_ok: false };
}

// @n8n-entry
const request = $('Preparar resumo').first().json;
const config = $('Config').first().json;
const { message, ai_ok } = extractDigest(request, $input.first().json);
return [
  {
    json: {
      message,
      ai_ok,
      digest_row: {
        period_start: request.report.period && request.report.period.from,
        period_end: request.report.period && request.report.period.to,
        report: request.report,
        message,
        model: ai_ok ? config.openai_model_digest : null,
      },
    },
  },
];

// One item per WhatsApp number in Config.digest_numbers.

function buildRecipients(numbers, message) {
  return (Array.isArray(numbers) ? numbers : [])
    .map((n) => String(n).replace(/\D/g, ''))
    .filter((n) => n.length >= 10)
    .map((number) => ({ number, text: message }));
}

// @n8n-entry
const config = $('Config').first().json;
const message = $('Montar mensagem').first().json.message;
return buildRecipients(config.digest_numbers, message).map((r) => ({ json: r }));
